using System;using System.IO;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
internal static class TestLyricBackgroundUi {
 static Form form;static WebView2 view;static string root,output;static int checks;
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool SetProcessDPIAware();
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern uint GetDpiForWindow(IntPtr window);
 static Task<string> Eval(string source){return view.CoreWebView2.ExecuteScriptAsync(source);}
 static async Task Assert(string source,string label){if(await Eval(source)!="true")throw new Exception(label);checks++;File.AppendAllText(Path.Combine(output,"ui-checks.txt"),"PASS "+label+Environment.NewLine);}
 static async Task Capture(string name){using(var f=File.Create(Path.Combine(output,name+".png")))await view.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,f);}
 static async Task Run(){
  using(var b=new Bitmap(1200,800))using(var g=Graphics.FromImage(b))using(var brush=new System.Drawing.Drawing2D.LinearGradientBrush(new Rectangle(0,0,1200,800),Color.FromArgb(126,154,184),Color.FromArgb(25,48,81),35)){g.FillRectangle(brush,0,0,1200,800);b.Save(Path.Combine(root,"wallpaper.png"));}
  await view.EnsureCoreWebView2Async(await CoreWebView2Environment.CreateAsync(null,Path.Combine(root,"test-runtime")));view.ZoomFactor=96.0/GetDpiForWindow(form.Handle);view.CoreWebView2.SetVirtualHostNameToFolderMapping("prism-test.local",root,CoreWebView2HostResourceAccessKind.DenyCors);
  view.CoreWebView2.WebMessageReceived+=(s,e)=>{var message=e.TryGetWebMessageAsString();if(!message.StartsWith("dock-icons:"))return;var parts=message.Split(':');view.CoreWebView2.PostWebMessageAsJson("{\"type\":\"dock-icons-ack\",\"sequence\":"+parts[1]+",\"alpha\":"+parts[2]+"}");};
  await view.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync("window.__errors=[];addEventListener('error',e=>__errors.push(e.message));");view.Source=new Uri("https://prism-test.local/index.html");
  for(int i=0;i<100;i++){if(await Eval("!!window.PrismLyrics&&!!document.querySelector('#dock-lyrics')&&document.readyState==='complete'")=="true")break;await Task.Delay(50);}
  await Eval(File.ReadAllText(Path.Combine(root,"TestLyricBackgroundUi.js")));
  await Eval("runLyricBackgroundChecks().then(result=>window.__backgroundResults=result).catch(e=>window.__backgroundError=e.stack)");
  for(int i=0;i<100;i++){if(await Eval("!!window.__backgroundResults||!!window.__backgroundError")=="true")break;await Task.Delay(100);}
  string error=await Eval("window.__backgroundError||''");await Assert("!!window.__backgroundResults","actual Dock background interactions: "+error);
  File.AppendAllText(Path.Combine(output,"ui-checks.txt"),await Eval("JSON.stringify(__backgroundResults)")+Environment.NewLine);
  await Eval("chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'lyrics',show:true,current:'把这一刻，留在光里',next:'下一句 · 风从身边经过',motionPaused:false,appearance:{backgroundTheme:'album',backgroundOpacity:85,backgroundMotion:true,effect:'none'},palette:{album:['#a9663c','#315f4c','#8b493d'],wallpaper:['#284e7c','#3b6374','#4c416d']}}}))");await Task.Delay(1000);
  foreach(int seconds in new[]{0,8,16}){await Eval("document.querySelector('.lyric-background').getAnimations({subtree:true}).filter(a=>a.id!=='lyric-background-transition').forEach(a=>{a.pause();a.currentTime="+(seconds*1000)+"})");await Task.Delay(60);await Capture("lyric-color-flow-"+seconds);}
  form.ClientSize=new Size(1200,240);
  await Eval("chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'layout',width:1200,height:240,theme:'Sky',paused:false,cards:[{name:'Dock',x:65,y:100,w:1070,h:100,r:28,insetY:16}]}}));chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'lyrics',show:true,current:'把这一刻，留在光里',next:'下一句 · 风从身边经过',motionPaused:false,appearance:{widthMode:'fixed',width:900,backgroundTheme:'album',backgroundOpacity:60,backgroundMotion:true,effect:'none'},palette:{album:['#b15748','#2f8d80','#5a8440'],wallpaper:['#284e7c','#3b6374','#4c416d']}}}))");await Task.Delay(1300);await Capture("lyric-background-preview");
  await Assert("__errors.length===0","no JavaScript errors during background playback");File.AppendAllText(Path.Combine(output,"ui-checks.txt"),"Completed "+checks+" background host checks."+Environment.NewLine);
  form.ClientSize=new Size(1000,720);view.Source=new Uri("https://prism-test.local/workspace.html");for(int i=0;i<100;i++){if(await Eval("!!document.querySelector('#lyrics-preview')&&!!window.PrismWorkspace&&document.readyState==='complete'")=="true")break;await Task.Delay(50);}
  await Eval("PrismWorkspace.receive({type:'settings',snapshot:{theme:'Sky',revision:1,glassOpacity:100,textScale:100,reducedMotion:false,gridColumns:6,showLabels:true,monitors:[]}});PrismWorkspace.open('settings');document.querySelector('[data-page=lyrics]').click();document.querySelector('#lyrics-preview').scrollIntoView({block:'start'})");
  await Eval("window.__backgroundMessages=[];chrome.webview.postMessage=m=>__backgroundMessages.push(m);dispatchEvent(new CustomEvent('prism-panel-change',{detail:{mode:'music'}}));chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'widgets',lyrics:{enabled:false,online:false,holdGaps:true,offsetMs:0,appearance:{backgroundTheme:'album',backgroundOpacity:60,backgroundMotion:true},palette:{album:['#a34c44','#33866e','#646b31'],wallpaper:['#284e7c','#3b6374','#4c416d'],status:'使用当前专辑的配色'}}}}))");await Task.Delay(150);
  await Assert("document.querySelector('[data-lyric-field=backgroundTheme]').value==='album'&&document.querySelector('#lyrics-preview').dataset.backgroundFlow==='true'","unified settings preview uses the same album color layer");
  await Capture("lyric-background-settings-preview");
  await Eval("document.querySelector('[data-lyric-preset]').click()");await Task.Delay(200);
  await Assert("__backgroundMessages.some(m=>{if(!m.startsWith('action:lyrics-style:'))return false;const s=JSON.parse(m.slice(20));return s.backgroundTheme==='album'&&s.backgroundOpacity===60&&s.backgroundMotion})","text preset preserves all independent background settings");
  await Eval("chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'layout',width:1200,height:240,sceneWidth:1200,sceneHeight:240,originX:0,originY:0,theme:'Sky',paused:true}}))");await Task.Delay(80);
  await Assert("document.querySelector('#lyrics-preview').dataset.backgroundFlow==='false'&&!document.querySelector('#lyrics-preview .lyric-background').getAnimations({subtree:true}).some(a=>a.playState==='running')","settings layout pause also stops background preview");
  await Eval("chrome.webview.dispatchEvent(new MessageEvent('message',{data:{type:'layout',width:1000,height:720,sceneWidth:1200,sceneHeight:800,originX:0,originY:0,theme:'Sky',paused:false}}))");await Task.Delay(80);
  await Assert("document.querySelector('#lyrics-preview').dataset.backgroundFlow==='true'&&document.querySelector('#lyrics-preview .lyric-background').getAnimations({subtree:true}).some(a=>a.playState==='running')","clearing layout pause restores the selected background motion");
  File.AppendAllText(Path.Combine(output,"ui-checks.txt"),"Completed "+checks+" total background host checks."+Environment.NewLine);
 }
 [STAThread]static void Main(string[] args){SetProcessDPIAware();root=Path.GetFullPath(args[0]);output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);Application.EnableVisualStyles();form=new Form{ClientSize=new Size(1200,800),FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Location=new Point(-16000,-16000),ShowInTaskbar=false};view=new WebView2{Dock=DockStyle.Fill};form.Controls.Add(view);form.Shown+=async(s,e)=>{try{await Run();}catch(Exception ex){File.AppendAllText(Path.Combine(output,"ui-checks.txt"),ex.ToString());Environment.ExitCode=1;}finally{view.Dispose();form.Close();}};Application.Run(form);}
}
